def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"[^0-9]", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    normalized = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        normalized.append({
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower()
                         in {"y", "yes", "true", "1"},
            "updated": parse_updated(row["updated"]),
            "_index": index,
        })

    # Union-find captures transitive matches.
    parent = list(range(len(normalized)))
    size = [1] * len(normalized)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        a, b = find(a), find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    emails = {}
    phone_names = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            key = row["email"]
            if key in emails:
                union(i, emails[key])
            else:
                emails[key] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_names:
                union(i, phone_names[key])
            else:
                phone_names[key] = i

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["_index"] for row in group),
    )

    result = []
    for group in ordered_groups:
        preferred = sorted(
            group,
            key=lambda row: (
                row["source"] == "manual",
                row["updated"],
                -row["_index"],
            ),
            reverse=True,
        )

        person = {}
        for field in (
            "first_name", "last_name", "zip", "email", "phone", "source"
        ):
            person[field] = next(
                (row[field] for row in preferred if row[field]), ""
            )

        tags = set()
        for row in group:
            tags.update(row["tags"])

        person["tags"] = ";".join(sorted(tags))
        person["opted_out"] = (
            "Y" if any(row["opted_out"] for row in group) else "N"
        )
        person["updated"] = max(
            row["updated"] for row in group
        ).strftime("%Y-%m-%d")

        result.append(person)

    # Opted-out people remain marked "Y"; exclude them before sending.
    return result
